defmodule JoobQ.Worker.AcksTest do
  use ExUnit.Case, async: true

  alias JoobQ.Error
  alias JoobQ.Worker.{Acks, Leases}

  test "sends once 100 wait, or when the linger is over, and one call at a time" do
    assert Acks.decide(100, 100, 5, false, nil) == :send
    assert Acks.decide(3, 100, 5, false, nil) == :linger
    assert Acks.decide(3, 100, 5, false, make_ref()) == :wait
    assert Acks.decide(3, 100, 5, false, :due) == :send
    assert Acks.decide(3, 100, 0, false, nil) == :send
    assert Acks.decide(100, 100, 5, true, :due) == :wait
    assert Acks.decide(0, 100, 5, false, :due) == :wait
  end

  test "a call carries the first outcomes, in order" do
    queue = :queue.from_list(Enum.to_list(1..150))
    {batch, rest} = Acks.take(queue, 100)
    assert batch == Enum.to_list(1..100)
    assert :queue.to_list(rest) == Enum.to_list(101..150)
    assert {[1, 2], _empty} = Acks.take(:queue.from_list([1, 2]), 100)
  end

  test "an unanswered or 5xx call is sent again, a refused one is not, a too large one in halves" do
    assert Acks.verdict({:ok, %{"results" => []}}, 3) == :done
    assert Acks.verdict({:error, %Error{reason: :transport}}, 3) == :retry
    assert Acks.verdict({:error, %Error{reason: :unavailable, status: 503}}, 3) == :retry
    assert Acks.verdict({:error, %Error{reason: :gateway, status: 429}}, 3) == :retry
    assert Acks.verdict({:error, %Error{reason: :gateway, status: 413}}, 3) == :split
    assert Acks.verdict({:error, %Error{reason: :gateway, status: 413}}, 1) == :drop
    assert Acks.verdict({:error, %Error{reason: :unauthorized, status: 401}}, 3) == :drop
  end

  test "names the refused items by their codes, never their outcomes" do
    results = [
      %{"lease_token" => "a", "status" => "completed", "error" => nil},
      %{"lease_token" => "b", "status" => "error", "error" => %{"code" => "not_found"}}
    ]

    assert Acks.refused({:ok, %{"results" => results}}) =~ "1 outcome(s) (not_found)"
    assert Acks.refused({:ok, %{"results" => Enum.take(results, 1)}}) == nil

    malformed = [%{"status" => "error", "error" => "x"}, %{"status" => "error"}, "x"]
    assert Acks.refused({:ok, %{"results" => malformed}}) =~ "2 outcome(s) (unknown)"
    assert Acks.refused({:ok, %{"results" => "x"}}) == nil
  end

  test "leases are held, renewed, cancelled and released; without a table nothing breaks" do
    name = :"leases_#{System.unique_integer([:positive])}"
    assert Leases.tokens(name) == [] and Leases.count(name) == 0
    Leases.new(name)
    Leases.hold(name, ["a", "b", "c"])
    assert Enum.sort(Leases.tokens(name)) == ["a", "b", "c"]

    Leases.renewed(name, [
      %{"lease_token" => "a", "cancel_requested" => true, "error" => nil},
      %{"lease_token" => "b", "cancel_requested" => false, "error" => %{"code" => "not_found"}}
    ])

    assert Leases.cancel_requested?(name, "a")
    refute Leases.cancel_requested?(name, "c")
    Leases.release(name, ["c"])
    assert Leases.tokens(name) == ["a"]
  end
end
